fn hex(comptime s: []const u8) Fr {
    comptime {
        var b: [32]u8 = [_]u8{0} ** 32;
        var i: usize = 0;
        while (i < 32) : (i += 1) {
            const hi = std.fmt.charToDigit(s[2 + i*2], 16) catch 0;
            const lo = std.fmt.charToDigit(s[2 + i*2 + 1], 16) catch 0;
            b[31 - i] = (hi << 4) | lo;
        }
        return Fr.fromBytes(b);
    }
}
