fn sbox(x: Fr) Fr {
    const x2 = x.mul(x);
    const x4 = x2.mul(x2);
    return x4.mul(x); // x^5
}

fn matmul(s: [T]Fr) [T]Fr {
    var out: [T]Fr = undefined;
    for (0..T) |i| {
        out[i] = Fr.zero;
        for (0..T) |j| out[i] = out[i].add(P[i][j].mul(s[j]));
    }
    return out;
}

pub fn poseidon_perm(mut state: [T]Fr) [T]Fr {
    var round: usize = 0;
    // Full rounds
    while (round < RF / 2) : (round += 1) {
        for (0..T) |i| state[i] = state[i].add(C[round*T + i]);
        for (0..T) |i| state[i] = sbox(state[i]);
        state = matmul(state);
    }
    // Partial rounds
    while (round < RF / 2 + RP) : (round += 1) {
        for (0..T) |i| state[i] = state[i].add(C[round*T + i]);
        state[0] = sbox(state[0]);
        state = matmul(state);
    }
    // Full rounds
    while (round < ROUNDS) : (round += 1) {
        for (0..T) |i| state[i] = state[i].add(C[round*T + i]);
        for (0..T) |i| state[i] = sbox(state[i]);
        state = matmul(state);
    }
    return state;
}